        4651, 4652, 4653, 4654, 4655, 4656, 4657, 4659, 4660, 4661, 4662, 4663, 4664, 4665, 4667, 4668,
        4670, 4672, 4673, 4675, 4676, 4677, 4679, 4680, 4684, 4688, 4681, 4682, 4683, 4685, 4686, 4687,
        4689, 4690, 4691,
    };

    public static bool TryMatchLongest(string value, int startIndex, out int consumedLength, out int glyphIndex)
    {
        consumedLength = 0;
        glyphIndex = -1;
        if (string.IsNullOrEmpty(value) || (uint)startIndex >= (uint)value.Length)
        {
            return false;
        }

        var nodeIndex = 0;
        var position = startIndex;
        while (position < value.Length)
        {
            ReadCodePoint(value, position, out var codepoint, out var codeUnitLength);
            if (codepoint == VariationSelector16)
            {
                position += codeUnitLength;
                if (TrieTerminals[nodeIndex] >= 0)
                {
                    consumedLength = position - startIndex;
                    glyphIndex = TrieTerminals[nodeIndex];
                }
                continue;
            }

            var childIndex = FindChild(nodeIndex, codepoint);
            if (childIndex < 0)
            {
                break;
            }

            position += codeUnitLength;
            nodeIndex = childIndex;
            if (TrieTerminals[nodeIndex] >= 0)
            {
                consumedLength = position - startIndex;
                glyphIndex = TrieTerminals[nodeIndex];
            }
        }

        return glyphIndex >= 0;
    }

    public static int ReadCodePoint(string value, int index, out uint codepoint)
    {
        ReadCodePoint(value, index, out codepoint, out var codeUnitLength);
        return codeUnitLength;
    }

    private static int FindChild(int nodeIndex, uint codepoint)
    {
        var low = TrieFirstEdges[nodeIndex];
        var high = low + TrieEdgeCounts[nodeIndex] - 1;
        while (low <= high)
        {
            var middle = low + ((high - low) >> 1);
            var candidate = TrieEdgeCodePoints[middle];
            if (candidate == codepoint)
            {
                return TrieEdgeTargets[middle];
            }

            if (candidate < codepoint)
            {
                low = middle + 1;
            }
            else
            {
                high = middle - 1;
            }
        }

        return -1;
    }

    private static void ReadCodePoint(string value, int index, out uint codepoint, out int codeUnitLength)
    {
        var current = value[index];
        if (char.IsHighSurrogate(current) &&
            index + 1 < value.Length &&
            char.IsLowSurrogate(value[index + 1]))
        {
            codepoint = (uint)char.ConvertToUtf32(current, value[index + 1]);
            codeUnitLength = 2;
            return;
        }

        codepoint = current;
        codeUnitLength = 1;
    }
}
